let user
try {
    user = await Noodl.Users.logIn(Inputs.Username,Inputs.Password)
}
catch(e) {
    Outputs.Failure();
}

Outputs.SessionToken = user.sessionToken
Outputs.Success();

try {
    await Noodl.Records.save(Noodl.Users.Current.UserId,{
        logInDisabled: true
    })
}
catch(e) {
    Outputs.Failure()
    throw e;
}

Outputs.Success()

const endpoint = "https://toolbox.noodl.cloud/speakeasy"

const res = await fetch(endpoint + "/generate-secret",{
    method:'POST',
    headers:{
        'content-type':'application/json'
    },
    body:JSON.stringify({name:Inputs.Name})
})

if(res.ok) {
    const json = await res.json();

    Outputs.QRCode = json.qrcode;
    Outputs.Base32 = json.base32;

    Outputs.Success()
}
else Outputs.Failure()

try {
    await Noodl.Records.save(Noodl.Users.Current.UserId,{
        totp_secret: null,
        logInDisabled: false
    })
}
catch(e) {
    Outputs.Failure()
    throw e;
}

Outputs.Success()

Noodl.Users.Current.Properties.totp_secret = Inputs.Secret;

try {
    await Noodl.Users.Current.save()
}
catch(e) {
    Outputs.Failure()
    throw e;
}

Outputs.Success()

let user;
try {
    user = await Noodl.Users.logIn(Inputs.Username,Inputs.Password)
}
catch(e) {
    Outputs.Failure();
    throw e;
}

if(user.totp_secret) {
    // TOTP is enabled, need extra login step
    Outputs.SessionToken = null;
    Outputs.Success();
}
else {
    // TOTP is not enabled, return session token
    Outputs.SessionToken = user.sessionToken;
    Outputs.Success();
}

const endpoint = "https://toolbox.noodl.cloud/speakeasy"

const res = await fetch(endpoint + "/verify-token",{
    method:'POST',
    headers:{
        'content-type':'application/json'
    },
    body:JSON.stringify({base32:Inputs.Base32,token:Inputs.Token})
})

if(res.ok) {
    Outputs.Success()
}
else Outputs.Failure()

try {
    await Noodl.Users.become(Inputs.SessionToken)
}
catch(e) {
    Outputs.Failure()
    throw e;
}

Outputs.Success()

if(Inputs.SessionToken === null || Inputs.SessionToken === undefined) {
    Outputs.TOTPNeeded();
    return;
}

try {
    await Noodl.Users.become(Inputs.SessionToken)
}
catch(e) {
    Outputs.Failure()
    throw e;
}

Outputs.Success();
